from pathlib import Path

ROOT=Path('/app/piton/verif/env')

def vmh_bits(path):
    vals=[]
    for raw in Path(path).read_text().splitlines():
        line=raw.split('//')[0].strip()
        if not line or line.startswith('/*') or line.startswith('*') or line.startswith('*/'):
            continue
        s=line.replace('_','')
        if s and set(s) <= {'0','1'}:
            vals.append(int(s,2))
    return vals

def vmh_hex(path):
    vals=[]
    for raw in Path(path).read_text().splitlines():
        line=raw.split('//')[0].strip()
        if not line or line.startswith('/*') or line.startswith('*') or line.startswith('*/'):
            continue
        s=line.replace('_','')
        if s and set(s.lower()) <= set('0123456789abcdef'):
            vals.append(int(s,16))
    return vals

def compare(name, got, exp):
    if got != exp:
        for i,(g,e) in enumerate(zip(got,exp)):
            if g != e:
                raise AssertionError(f'{name}: mismatch at {i}: got {g:x}, expected {e:x}')
        raise AssertionError(f'{name}: length got {len(got)}, expected {len(exp)}')
    print(f'PASS {name} ({len(exp)} vectors)')

# Counter vectors: output index i observes source index i-2 after the FF update.
for stem in ['test_clear','test_clear_set','test_pause','test_set','test_step','test_step_clear','test_step_clear_set','test_step_set']:
    src=vmh_bits(ROOT/'ifu_esl_counter/test_cases'/f'{stem}_src.vmh')
    exp=vmh_bits(ROOT/'ifu_esl_counter/test_cases'/f'{stem}_sink.vmh')
    state=0
    got=[]
    for i in range(len(exp)):
        if i >= 2 and i-2 < len(src):
            bits=src[i-2]
            step=bits & 1
            clear=(bits >> 1) & 1
            set_=(bits >> 2) & 1
            if clear:
                state=0
            elif set_:
                state=1
            elif step:
                state=(state+1) & 0xffff
        got.append(state)
    compare('counter/'+stem, got, exp)

# Shift register vectors use the same two-cycle source visibility.
mask49=(1<<49)-1
for stem in ['test_pause','test_set','test_set_shift','test_shift']:
    src=vmh_bits(ROOT/'ifu_esl_shiftreg/test_cases'/f'{stem}_src.vmh')
    exp=vmh_bits(ROOT/'ifu_esl_shiftreg/test_cases'/f'{stem}_sink.vmh')
    state=0
    got=[]
    for i in range(len(exp)):
        if i >= 2 and i-2 < len(src):
            bits=src[i-2]
            step=bits & 1
            set_=(bits >> 1) & 1
            if set_:
                state=1
            elif step:
                state=((state << 1) & mask49) | ((state >> 48) & 1)
        got.append(state)
    compare('shiftreg/'+stem, got, exp)

# LFSR: load has priority over step; feedback taps 15,13,12,10 into bit 0.
for stem in ['test_exhaust','test_ldstep','test_pause','test_seed','test_state0']:
    src=vmh_bits(ROOT/'ifu_esl_lfsr/test_cases'/f'{stem}_src.vmh')
    exp=vmh_bits(ROOT/'ifu_esl_lfsr/test_cases'/f'{stem}_sink.vmh')
    state=0
    got=[]
    for i in range(len(exp)):
        if i >= 2 and i-2 < len(src):
            bits=src[i-2]
            seed=bits & 0xffff
            ld=(bits >> 16) & 1
            step=(bits >> 17) & 1
            if ld:
                state=seed
            elif step:
                fb=((state>>15) ^ (state>>13) ^ (state>>12) ^ (state>>10)) & 1
                state=((state << 1) & 0xffff) | fb
        got.append((((state >> 15) & 1) << 16) | state)
    compare('lfsr/'+stem, got, exp)

# UART sink is simply each 240-bit source packet, most-significant byte first.
src=vmh_hex(ROOT/'uart_serializer/test_cases/test_src.vmh')
exp=vmh_hex(ROOT/'uart_serializer/test_cases/test_sink.vmh')
got=[]
for pkt in src:
    for shift in range(232, -1, -8):
        got.append((pkt >> shift) & 0xff)
compare('uart_serializer/test', got, exp)
